                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <!-- Font Size -->
            <h6 class="mb-2">Font Size</h6>
            <div class="d-flex gap-3 mb-4">
                @foreach (var size in _fontSizes)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <!-- Language -->
            <div class="mb-4">
                <h6 class="mb-2">Language</h6>
                <select class="form-select" style="max-width: 250px;" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="form-check form-switch mb-4">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>

            <!-- Live Preview -->
            <h6 class="mb-2">Preview</h6>
            <div class="border rounded @PreviewBgClass" style="@PreviewStyle">
                <div class="@(_compactMode ? "p-2" : "p-3")">
                    <h6 class="@PreviewTextClass mb-1" style="@PreviewFontStyle">Dashboard</h6>
                    <p class="@PreviewTextClass mb-2" style="@PreviewFontStyle">
                        This is a preview of how your content will look with the selected appearance settings.
                    </p>
                    <button class="btn btn-sm @PreviewBtnClass">Sample Button</button>
                </div>
            </div>

            <div class="mt-4">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save")
                </button>
            </div>
        }
    </div>
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _toast;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        await SettingsService.SaveAppearanceAsync(
            new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _toast = "Appearance settings saved!";
        _saving = false;
    }

    private string PreviewBgClass => _theme switch
    {
        "Dark" => "bg-dark",
        _ => "bg-light"
    };

    private string PreviewTextClass => _theme switch
    {
        "Dark" => "text-light",
        _ => "text-dark"
    };

    private string PreviewBtnClass => _theme switch
    {
        "Dark" => "btn-outline-light",
        _ => "btn-outline-dark"
    };

    private string PreviewStyle => _theme switch
    {
        "Dark" => "background-color: #1e1e1e;",
        _ => ""
    };

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };
}
