@inject ISettingsService SettingsService

<div class="card">
    <div class="card-header"><h5 class="mb-0">Profile</h5></div>
    <div class="card-body">
        @if (_loading)
        {
            <p class="text-muted">Loading profile…</p>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_toast))
            {
                <div class="alert alert-success alert-dismissible fade show" role="alert">
                    @_toast
                    <button type="button" class="btn-close" @onclick="() => _toast = null"></button>
                </div>
            }

            <div class="row mb-4">
                <div class="col-md-3 text-center">
                    <div class="avatar-preview mb-2">
                        <img src="@_avatarUrl" alt="Avatar" class="rounded-circle" width="100" height="100" />
                    </div>
                    <small class="text-muted text-break">@_avatarUrl</small>
                </div>
                <div class="col-md-9">
                    <div class="mb-3">
                        <label class="form-label">Display Name</label>
                        <input type="text" class="form-control" @bind="_displayName" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email</label>
                        <input type="email" class="form-control" @bind="_email" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Bio</label>
                        <textarea class="form-control" rows="3" @bind="_bio"></textarea>
                    </div>
                </div>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Changes")
                </button>
                <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
            </div>
        }
    </div>
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _toast;

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private UserProfile _savedProfile = default!;

    protected override async Task OnInitializedAsync()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _avatarUrl = p.AvatarUrl;
        _bio = p.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _toast = "Profile saved successfully!";
        _saving = false;
    }

    private void Discard()
    {
        ApplyProfile(_savedProfile);
        _toast = null;
    }
}

